const policyBaseOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

// Keep this as `base + base * RATE`. The algebraically equivalent
// `base * (1 + RATE)` is NOT safe here: 100 * 1.1 === 110.00000000000001 in
// IEEE-754, and Math.ceil turns that into 116 instead of 115. Ceil amplifies
// upward float error rather than absorbing it.
const quote = (items: Item[]): QuoteResult => {
  const policyBase = policyBaseOf(items);

  return {
    premium: Math.ceil(
      policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE,
    ),
  };
};
